import { useEffect, useMemo, useState } from "react";
import { usePortal, createLocalId } from "@/store/PortalStore";
import hero from "@/assets/skyarth-hero.jpg";

const navItems = [
  ["Buy", "/buy"], ["Rent", "/rent"], ["Commercial", "/commercial"],
  ["New Projects", "/projects"], ["Plots & Land", "/plots"], ["Services", "/services"],
  ["Insights", "/insights"], ["Contact", "/contact"],
];
const transactionOptions = ["Buy", "Rent", "Commercial Sale", "Commercial Lease", "New Projects", "Residential Plots", "Commercial Plots", "Agricultural Land"];
const categories = ["Residential", "Commercial", "Plot"];
const propertyTypes = ["Apartment", "Flat", "Penthouse", "Villa", "Independent House", "Builder Floor", "Studio Apartment", "Office Space", "Retail Shop", "Showroom", "Warehouse", "Industrial Property", "Residential Plot", "Commercial Plot", "Agricultural Land"];
const leadStatuses = ["New", "Contacted", "Qualified", "Site Visit Scheduled", "Negotiation", "Converted", "Closed", "Not Interested"];
const formatPrice = (amount, compact = false) => {
  if (amount == null || Number.isNaN(Number(amount))) return "Price on enquiry";
  const value = Number(amount);
  if (compact && value >= 10000000) return `₹${(value / 10000000).toFixed(value % 10000000 === 0 ? 0 : 2)} Cr`;
  if (compact && value >= 100000) return `₹${(value / 100000).toFixed(value % 100000 === 0 ? 0 : 1)} L`;
  return new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(value);
};
const slug = (value) => String(value ?? "").toLowerCase().replaceAll(" ", "-");

function Icon({ name, size = 18 }) {
  const shared = { width: size, height: size, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 1.8, strokeLinecap: "round", strokeLinejoin: "round", "aria-hidden": true };
  const paths = {
    home: <><path d="m3 10 9-7 9 7"/><path d="M5 9v12h14V9M9 21v-7h6v7"/></>,
    search: <><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>,
    heart: <path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8l1 1L12 21l7.8-7.6 1-1a5.5 5.5 0 0 0 0-7.8Z"/>,
    phone: <><path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1A19.4 19.4 0 0 1 5.2 13a19.8 19.8 0 0 1-3.1-8.7A2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7l.5 3a2 2 0 0 1-.6 1.7L7.7 9.7a16 16 0 0 0 6.6 6.6l1.3-1.3a2 2 0 0 1 1.7-.6l3 .5a2 2 0 0 1 1.7 2Z"/></>,
    arrow: <><path d="M5 12h14"/><path d="m13 6 6 6-6 6"/></>,
    close: <><path d="m18 6-12 12M6 6l12 12"/></>,
    menu: <><path d="M4 6h16M4 12h16M4 18h16"/></>,
    pin: <><path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></>,
    compare: <><path d="M8 4v16M16 4v16M4 8h8M12 16h8"/></>,
    check: <path d="m5 12 4 4L19 6"/>,
    share: <><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.7 6.8-4.4M8.6 13.3l6.8 4.4"/></>,
  };
  return <svg {...shared}>{paths[name] ?? paths.home}</svg>;
}

function Brand({ light = false }) {
  return <a className={`brand ${light ? "brand-light" : ""}`} href="/" aria-label="SKYARTH Property home"><span className="brand-mark"><svg viewBox="0 0 40 40" role="img" aria-label=""><path d="M4 18 20 5l16 13v17H4Z"/><path d="M13 35V21h14v14M8 17h24"/><path d="M17 27h6"/></svg></span><span><strong>SKYARTH</strong><small>PROPERTY</small></span></a>;
}

function Header() {
  const { data } = usePortal();
  const [menuOpen, setMenuOpen] = useState(false);
  return <header className="site-header"><div className="header-main"><Brand/><nav className="desktop-nav" aria-label="Main navigation">{navItems.map(([label, href]) => <a href={href} key={href}>{label}</a>)}</nav><div className="header-actions"><a className="header-phone" href={`tel:${data.settings.phone}`}><Icon name="phone" size={16}/>{data.settings.phone}</a><a className="button button-small button-emerald header-list" href="/list-property">List Your Property <Icon name="arrow" size={15}/></a><button className="icon-button mobile-menu-button" aria-label={menuOpen ? "Close navigation" : "Open navigation"} onClick={() => setMenuOpen(!menuOpen)}><Icon name={menuOpen ? "close" : "menu"}/></button></div></div>{menuOpen && <nav className="mobile-nav" aria-label="Mobile navigation">{navItems.map(([label, href]) => <a href={href} key={href} onClick={() => setMenuOpen(false)}>{label}</a>)}<a href="/saved-properties">Saved properties</a><a href="/list-property">List your property</a><a href={`tel:${data.settings.phone}`}>Call {data.settings.phone}</a></nav>}</header>;
}

function Footer() {
  const { data } = usePortal();
  const addressQuery = encodeURIComponent(data.settings.address);
  return <footer className="site-footer"><div className="footer-inner"><div className="footer-brand-column"><Brand light/><p>Thoughtful guidance for homes, investments, commercial spaces and land.</p><span className="demo-label">DEMO INVENTORY · LOCAL BROWSER DATA</span></div><div><h3>Explore</h3><a href="/buy">Buy property</a><a href="/rent">Rent a home</a><a href="/commercial">Commercial</a><a href="/projects">New projects</a><a href="/plots">Plots &amp; land</a><a href="/services">Property services</a></div><div><h3>SKYARTH</h3><a href="/about">About us</a><a href="/contact">Contact</a><a href="/faq">FAQs</a><a href="/privacy-policy">Privacy policy</a><a href="/terms">Terms &amp; conditions</a><a href="/disclaimer">Disclaimer</a><a href="/admin/login">Admin Login</a></div><div><h3>Visit &amp; connect</h3><p>{data.settings.address}</p><a href={`tel:${data.settings.phone}`}>{data.settings.phone}</a><a href={`mailto:${data.settings.email}`}>{data.settings.email}</a><a href={`https://wa.me/${data.settings.whatsapp}?text=${encodeURIComponent("Hello SKYARTH Property, I would like to enquire about a property.")}`} target="_blank" rel="noreferrer">WhatsApp</a><a href={`https://www.google.com/maps/dir/?api=1&destination=${addressQuery}`} target="_blank" rel="noreferrer">Get directions</a></div></div><div className="footer-bottom"><span>© {new Date().getFullYear()} SKYARTH Property</span><span>Demo property information is illustrative. Please verify independently.</span></div></footer>;
}

function SiteLayout({ children }) {
  return <><Header/><main>{children}</main><Footer/></>;
}

function SectionHeading({ eyebrow, title, text, link, linkText }) {
  return <div className="section-heading"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2>{text && <p>{text}</p>}</div>{link && <a className="text-link" href={link}>{linkText ?? "Explore all"} <Icon name="arrow" size={16}/></a>}</div>;
}

function PropertyCard({ property, compact = false }) {
  const { data, update } = usePortal();
  const isSaved = data.saved.includes(property.id);
  const isCompared = data.compared.includes(property.id);
  const toggleSaved = () => update("saved", (items) => isSaved ? items.filter((id) => id !== property.id) : [...items, property.id]);
  const toggleCompare = () => update("compared", (items) => isCompared ? items.filter((id) => id !== property.id) : items.length >= 4 ? items : [...items, property.id]);
  const amount = property.transaction === "Rent" || property.transaction === "Commercial Lease" ? property.monthlyRent ?? property.price : property.price;
  return <article className={`property-card ${compact ? "property-card-compact" : ""}`}><div className="property-image-wrap"><a href={`/property/${property.id}`} aria-label={`View ${property.title}`}><img className="property-image" src={property.images?.[0] || hero} alt={`${property.type} in ${property.locality}, ${property.city}`} loading="lazy" width="720" height="480" onError={(event) => { event.currentTarget.src = hero; }}/></a><div className="property-badges">{property.featured && <span className="badge badge-gold">Featured</span>}{property.verified && <span className="badge badge-verified"><Icon name="check" size={12}/> Verified demo</span>}</div><button onClick={toggleSaved} className={`save-button ${isSaved ? "saved" : ""}`} aria-label={isSaved ? "Remove from saved properties" : "Save property"} title={isSaved ? "Remove saved property" : "Save property"}><Icon name="heart" size={18}/></button></div><div className="property-body"><div className="property-category-row"><span>{property.transaction}</span><span>{property.type}</span></div><h3><a href={`/property/${property.id}`}>{property.title}</a></h3><p className="property-place"><Icon name="pin" size={14}/>{property.locality}, {property.city}</p><div className="property-price-row"><strong>{formatPrice(amount, true)}{property.transaction === "Rent" || property.transaction === "Commercial Lease" ? <small> / month</small> : null}</strong>{property.pricePerSqft && <span>{formatPrice(property.pricePerSqft)} / sq.ft.</span>}</div><div className="property-stats"><span>{property.area.toLocaleString("en-IN")} {property.areaUnit}</span>{property.bedrooms ? <span>{property.bedrooms} beds</span> : null}{property.bathrooms ? <span>{property.bathrooms} baths</span> : null}</div><div className="property-card-footer"><label className="compare-label"><input type="checkbox" checked={isCompared} onChange={toggleCompare} disabled={!isCompared && data.compared.length >= 4}/> Compare</label><a className="text-link" href={`/property/${property.id}`}>View details <Icon name="arrow" size={15}/></a></div></div></article>;
}

function LeadForm({ title = "Enquire about this property", leadType = "Property enquiry", related = "", compact = false }) {
  const { addLead } = usePortal();
  const [status, setStatus] = useState("");
  const submit = (event) => {
    event.preventDefault();
    const fields = new FormData(event.currentTarget);
    if (!fields.get("consent")) { setStatus("Please confirm consent before sending your enquiry."); return; }
    const record = addLead({ name: String(fields.get("name")).trim(), phone: String(fields.get("phone")).trim(), email: String(fields.get("email")).trim(), type: String(fields.get("type") || leadType), related: related || String(fields.get("related") || ""), budget: String(fields.get("budget") || ""), preferredDate: String(fields.get("date") || ""), message: String(fields.get("message") || ""), source: "Website demo" });
    setStatus(`Enquiry saved in this browser. Reference ${record.id}.`);
    event.currentTarget.reset();
  };
  return <form className={`lead-form ${compact ? "lead-form-compact" : ""}`} onSubmit={submit}><h3>{title}</h3><div className="form-grid"><label>Full name<input name="name" autoComplete="name" placeholder="Your name" required minLength={2}/></label><label>Phone<input name="phone" autoComplete="tel" type="tel" placeholder="Your phone number" required pattern="[+()0-9 -]{8,}" title="Enter a valid phone number"/></label><label>Email<input name="email" autoComplete="email" type="email" placeholder="you@example.com" required/></label><label>Enquiry type<select name="type" defaultValue={leadType}><option>{leadType}</option><option>Request a callback</option><option>Property valuation</option><option>Site visit</option><option>Commercial enquiry</option></select></label>{!compact && <label>Preferred visit date<input name="date" type="date"/></label>}<label>Budget<input name="budget" placeholder="e.g. ₹1.2 Cr"/></label><label className="form-wide">Message<textarea name="message" rows="3" placeholder="Share a little about what you are looking for"/></label><label className="consent-label form-wide"><input name="consent" type="checkbox" required/><span>I agree to be contacted about this enquiry. Demo information stays in this browser.</span></label><div className="form-wide"><button className="button button-emerald" type="submit">Send enquiry <Icon name="arrow" size={16}/></button>{status && <p className="form-feedback" role="status">{status}</p>}</div></div></form>;
}

function SearchPanel({ initialTransaction = "Buy", initialLocation = "" }) {
  const [transaction, setTransaction] = useState(initialTransaction);
  return <form className="search-panel" onSubmit={(event) => {
    event.preventDefault();
    const values = new FormData(event.currentTarget);
    const params = new URLSearchParams({ transaction, locality: values.get("locality"), type: values.get("type"), max: values.get("max") });
    window.location.assign(`/properties?${params.toString()}`);
  }}><div className="search-tabs" role="tablist" aria-label="Transaction type">{["Buy", "Rent", "Commercial", "Projects", "Plots & Land"].map((item) => <button type="button" role="tab" aria-selected={transaction === item} className={transaction === item ? "active" : ""} onClick={() => setTransaction(item)} key={item}>{item}</button>)}</div><div className="search-fields"><label className="search-location"><span>Location</span><div><Icon name="pin" size={18}/><input name="locality" placeholder="City, locality or landmark" defaultValue={initialLocation}/></div></label><label><span>Property type</span><select name="type" defaultValue=""><option value="">Any property type</option>{propertyTypes.map((type) => <option key={type}>{type}</option>)}</select></label><label><span>Maximum budget</span><select name="max" defaultValue=""><option value="">Any budget</option><option value="8000000">Up to ₹80 L</option><option value="15000000">Up to ₹1.5 Cr</option><option value="30000000">Up to ₹3 Cr</option></select></label><button className="button button-emerald search-submit"><Icon name="search" size={18}/> Search properties</button></div><p className="search-assurance">Your property journey, guided with clarity.</p></form>;
}

function HomePage() {
  const { data } = usePortal();
  const featured = data.properties.filter((property) => property.published && property.featured).slice(0, 3);
  const recent = data.properties.filter((property) => property.published).slice(3, 7);
  return <SiteLayout><section className="home-hero" style={{ backgroundImage: `linear-gradient(90deg, oklch(0.13 0.04 243 / .86), oklch(0.13 0.04 243 / .4) 56%, oklch(0.13 0.04 243 / .08)), url(${hero})` }}><div className="hero-content"><span className="eyebrow eyebrow-light">PROPERTY DISCOVERY · PUNE &amp; BEYOND</span><h1>{data.settings.heroTitle}</h1><p>{data.settings.heroText}</p><div className="hero-actions"><a href="/properties" className="button button-emerald">Explore properties <Icon name="arrow" size={17}/></a><a href="/list-property" className="button button-outline-light">List your property</a></div><div className="hero-assurance"><span className="assurance-mark"><Icon name="check" size={15}/></span>Your property journey, guided with clarity.</div></div><div className="hero-caption">A considered place to begin your next move.</div></section><section className="search-section"><SearchPanel/></section><section className="content-section"><SectionHeading eyebrow="DISCOVER BY INTENT" title="Find the right kind of space" text="Start with the move you have in mind."/><div className="intent-grid">{[["Buy a home", "A considered selection of homes for your next chapter.", "/buy", "01"], ["Find a rental", "Find a place that fits the way you live today.", "/rent", "02"], ["Commercial spaces", "Spaces and opportunities for work and business.", "/commercial", "03"], ["Plots & land", "Explore land listings and ask the right questions.", "/plots", "04"]].map(([title, text, href, number]) => <a className="intent-item" href={href} key={title}><span className="intent-number">{number}</span><h3>{title}</h3><p>{text}</p><span className="text-link">Explore <Icon name="arrow" size={15}/></span></a>)}</div></section><section className="content-section featured-section"><div className="section-inner"><SectionHeading eyebrow="SELECTED DEMO LISTINGS" title="A few places to explore" text="Sample inventory for discovery; availability and details are illustrative." link="/properties" linkText="View all properties"/><div className="property-grid">{featured.map((property) => <PropertyCard key={property.id} property={property}/>)}</div></div></section><section className="editorial-band"><div className="editorial-copy"><span className="eyebrow">A CLEARER WAY FORWARD</span><h2>Better decisions start with a better conversation.</h2><p>From first search to site visit planning, find practical guidance at every step of your property journey.</p><a className="button button-navy" href="/services">Explore our services <Icon name="arrow" size={16}/></a></div><div className="editorial-image"><img src={hero} alt="Contemporary residential architecture in Pune at sunset" loading="lazy" width="800" height="560"/></div></section><section className="content-section"><SectionHeading eyebrow="LOCAL PERSPECTIVES" title="Get to know Pune, one locality at a time" text="Illustrative guides to the neighbourhoods that make up the city." link="/locality-insights" linkText="Explore localities"/><div className="locality-pills">{data.localities.slice(0, 8).map((locality) => <a href={`/locality/${locality.slug}`} key={locality.slug}><Icon name="pin" size={15}/>{locality.name}<Icon name="arrow" size={14}/></a>)}</div></section><section className="trust-strip"><span>Thoughtful property discovery</span><span>Site visit coordination</span><span>Clear next steps</span><span>Independent verification encouraged</span></section><section className="content-section"><SectionHeading eyebrow="MORE TO EXPLORE" title="Explore more possibilities"/><div className="property-grid property-grid-small">{recent.slice(0, 3).map((property) => <PropertyCard key={property.id} property={property} compact/>)}</div></section></SiteLayout>;
}

function filterProperties(items, params) {
  const transaction = params.get("transaction") || "";
  const locality = (params.get("locality") || "").toLowerCase();
  const type = params.get("type") || "";
  const min = Number(params.get("min") || 0);
  const max = Number(params.get("max") || Infinity);
  const city = (params.get("city") || "").toLowerCase();
  const bedrooms = Number(params.get("bedrooms") || 0);
  const term = (params.get("q") || "").toLowerCase();
  const verified = params.get("verified") === "true";
  return items.filter((property) => {
    const amount = property.transaction === "Rent" || property.transaction === "Commercial Lease" ? property.monthlyRent ?? property.price : property.price;
    return property.published && (!transaction || transaction === "Commercial" ? !transaction || property.category === "Commercial" : property.transaction.toLowerCase() === transaction.toLowerCase() || transaction === "Projects" && property.transaction === "New Projects" || transaction === "Plots & Land" && property.category === "Plot") && (!locality || property.locality.toLowerCase().includes(locality)) && (!city || property.city.toLowerCase().includes(city)) && (!type || property.type === type) && amount >= min && amount <= max && (!bedrooms || (property.bedrooms ?? 0) >= bedrooms) && (!verified || property.verified) && (!term || `${property.title} ${property.locality} ${property.city} ${property.type}`.toLowerCase().includes(term));
  });
}

function PropertiesPage({ searchStr = "", preset = "" }) {
  const { data } = usePortal();
  const params = useMemo(() => new URLSearchParams(searchStr), [searchStr]);
  if (preset && !params.has("transaction")) params.set("transaction", preset);
  const [filters, setFilters] = useState({ q: params.get("q") ?? "", locality: params.get("locality") ?? "", city: params.get("city") ?? "", transaction: params.get("transaction") ?? "", type: params.get("type") ?? "", min: params.get("min") ?? "", max: params.get("max") ?? "", bedrooms: params.get("bedrooms") ?? "", verified: params.get("verified") === "true" });
  const [sort, setSort] = useState("newest");
  const [view, setView] = useState("grid");
  const [showMobileFilters, setShowMobileFilters] = useState(false);
  const [pageSize, setPageSize] = useState(9);
  const results = filterProperties(data.properties, new URLSearchParams(Object.entries(filters).filter(([, value]) => value !== "" && value !== false)));
  const sorted = [...results].sort((a, b) => sort === "price-low" ? a.price - b.price : sort === "price-high" ? b.price - a.price : sort === "area" ? b.area - a.area : sort === "featured" ? Number(b.featured) - Number(a.featured) : 0);
  const setFilter = (name, value) => setFilters((current) => ({ ...current, [name]: value }));
  const form = <form className="filter-form" onSubmit={(event) => event.preventDefault()}><div className="filter-head"><h3>Filters</h3><button type="button" className="plain-button" onClick={() => setFilters({ q: "", locality: "", city: "", transaction: "", type: "", min: "", max: "", bedrooms: "", verified: false })}>Clear all</button></div><label>Search<input value={filters.q} onChange={(event) => setFilter("q", event.target.value)} placeholder="Property, project, locality"/></label><label>Transaction<select value={filters.transaction} onChange={(event) => setFilter("transaction", event.target.value)}><option value="">Any transaction</option>{transactionOptions.map((item) => <option key={item}>{item}</option>)}</select></label><label>Property type<select value={filters.type} onChange={(event) => setFilter("type", event.target.value)}><option value="">Any property type</option>{propertyTypes.map((item) => <option key={item}>{item}</option>)}</select></label><label>City<input value={filters.city} onChange={(event) => setFilter("city", event.target.value)} placeholder="Any city"/></label><label>Locality<input value={filters.locality} onChange={(event) => setFilter("locality", event.target.value)} placeholder="Area or neighbourhood"/></label><div className="filter-two"><label>Min budget<input type="number" min="0" value={filters.min} onChange={(event) => setFilter("min", event.target.value)} placeholder="₹ min"/></label><label>Max budget<input type="number" min="0" value={filters.max} onChange={(event) => setFilter("max", event.target.value)} placeholder="₹ max"/></label></div><label>Bedrooms<select value={filters.bedrooms} onChange={(event) => setFilter("bedrooms", event.target.value)}><option value="">Any</option>{[1, 2, 3, 4].map((n) => <option key={n} value={n}>{n}+ bedrooms</option>)}</select></label><label className="consent-label"><input type="checkbox" checked={filters.verified} onChange={(event) => setFilter("verified", event.target.checked)}/> Explicitly marked verified</label></form>;
  return <SiteLayout><div className="page-heading-band"><div className="page-width"><span className="eyebrow">PUNE &amp; INDIA · DEMO LISTINGS</span><h1>Find your next place</h1><p>Browse the sample collection and filter by what matters to you.</p></div></div><section className="results-section page-width"><div className="mobile-filter-bar"><button className="button button-outline" onClick={() => setShowMobileFilters(true)}><Icon name="search"/> Filters</button><span>{sorted.length} properties</span></div><aside className={`filter-sidebar ${showMobileFilters ? "filter-sidebar-open" : ""}`}>{showMobileFilters && <button className="filter-close" aria-label="Close filters" onClick={() => setShowMobileFilters(false)}><Icon name="close"/></button>}{form}<button className="button button-emerald filter-apply-mobile" onClick={() => setShowMobileFilters(false)}>Show {sorted.length} properties</button></aside><div className="results-main"><div className="results-toolbar"><div><h2>{sorted.length} properties to explore</h2><p>Demo listings · details are illustrative</p></div><div className="result-controls"><label className="sort-select"><span>Sort by</span><select value={sort} onChange={(event) => setSort(event.target.value)}><option value="newest">Newest</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="area">Area</option><option value="featured">Featured</option></select></label><div className="view-toggle"><button className={view === "grid" ? "active" : ""} aria-label="Grid view" onClick={() => setView("grid")}>▦</button><button className={view === "list" ? "active" : ""} aria-label="List view" onClick={() => setView("list")}>☷</button></div></div></div>{Object.entries(filters).filter(([, value]) => value && value !== false).length > 0 && <div className="filter-chips">{Object.entries(filters).filter(([, value]) => value && value !== false).map(([name, value]) => <button key={name} onClick={() => setFilter(name, name === "verified" ? false : "")}>{name === "verified" ? "Verified" : value} ×</button>)}<button className="clear-chip" onClick={() => setFilters({ q: "", locality: "", city: "", transaction: "", type: "", min: "", max: "", bedrooms: "", verified: false })}>Clear all</button></div>}{sorted.length ? <div className={`property-grid ${view === "list" ? "property-list-view" : ""}`}>{sorted.slice(0, pageSize).map((property) => <PropertyCard key={property.id} property={property}/>)}</div> : <div className="empty-state"><span className="empty-icon"><Icon name="search" size={26}/></span><h2>No properties found</h2><p>Try a wider budget or remove a filter to see more demo listings.</p><button className="button button-outline" onClick={() => setFilters({ q: "", locality: "", city: "", transaction: "", type: "", min: "", max: "", bedrooms: "", verified: false })}>Clear filters</button></div>}{sorted.length > pageSize && <div className="load-more-wrap"><button className="button button-outline" onClick={() => setPageSize((count) => count + 9)}>Load more properties</button></div>}</div></section></SiteLayout>;
}

function PropertyDetail({ id }) {
  const { data, update } = usePortal();
  const property = data.properties.find((entry) => entry.id === id && entry.published);
  const [activeImage, setActiveImage] = useState(0);
  const [notice, setNotice] = useState("");
  useEffect(() => { if (property) update("recent", (items) => [property.id, ...items.filter((item) => item !== property.id)].slice(0, 20)); }, [property?.id]);
  if (!property) return <NotFoundPage/>;
  const images = property.images?.length ? property.images : [hero];
  const related = data.properties.filter((item) => item.id !== property.id && item.published && (item.locality === property.locality || item.category === property.category)).slice(0, 3);
  const price = property.transaction === "Rent" || property.transaction === "Commercial Lease" ? property.monthlyRent ?? property.price : property.price;
  const share = async () => {
    const url = window.location.href;
    try { if (navigator.share) await navigator.share({ title: property.title, url }); else { await navigator.clipboard.writeText(url); setNotice("Property link copied."); } } catch { setNotice("Property link is ready to share."); }
  };
  return <SiteLayout><section className="detail-top page-width"><div className="breadcrumbs"><a href="/">Home</a><span>/</span><a href="/properties">Properties</a><span>/</span><span>{property.locality}</span></div><div className="detail-title-row"><div><span className="eyebrow">{property.transaction} · {property.type}</span><h1>{property.title}</h1><p className="property-place"><Icon name="pin"/>{property.locality}, {property.city}</p></div><button className="button button-outline detail-share" onClick={share}><Icon name="share"/> Share</button></div><div className="detail-gallery"><div className="gallery-main"><img src={images[activeImage] ?? hero} alt={`${property.title} property image ${activeImage + 1}`} width="1200" height="760" onError={(event) => { event.currentTarget.src = hero; }}/><button className="gallery-arrow gallery-prev" aria-label="Previous image" onClick={() => setActiveImage((activeImage + images.length - 1) % images.length)}>‹</button><button className="gallery-arrow gallery-next" aria-label="Next image" onClick={() => setActiveImage((activeImage + 1) % images.length)}>›</button><span className="gallery-count">{activeImage + 1} / {images.length}</span></div><div className="gallery-thumbs">{images.map((image, index) => <button className={activeImage === index ? "active" : ""} onClick={() => setActiveImage(index)} key={`${image}-${index}`} aria-label={`Show image ${index + 1}`}><img src={image} alt=""/></button>)}</div></div></section><section className="detail-layout page-width"><div className="detail-content"><div className="detail-price-panel"><div><span>Asking {property.transaction === "Rent" || property.transaction === "Commercial Lease" ? "rent" : "price"}</span><strong>{formatPrice(price, true)}{property.transaction === "Rent" || property.transaction === "Commercial Lease" ? <small> / month</small> : null}</strong></div><div><span>Area</span><strong>{property.area.toLocaleString("en-IN")} {property.areaUnit}</strong></div><div><span>Price per sq.ft.</span><strong>{formatPrice(price / property.area)}</strong></div><div className="detail-action-group"><button className={`icon-button ${data.saved.includes(id) ? "saved" : ""}`} onClick={() => update("saved", (list) => list.includes(id) ? list.filter((entry) => entry !== id) : [...list, id])} aria-label="Save property"><Icon name="heart"/></button><label className="compare-label"><input type="checkbox" checked={data.compared.includes(id)} onChange={() => update("compared", (list) => list.includes(id) ? list.filter((entry) => entry !== id) : list.length < 4 ? [...list, id] : list)}/> Compare</label></div></div><div className="detail-section"><h2>About this property</h2><p>{property.description}</p></div><div className="detail-section"><h2>Property details</h2><div className="spec-grid">{[["Property type", property.type], ["Transaction", property.transaction], ["Area", `${property.area.toLocaleString("en-IN")} ${property.areaUnit}`], ["Bedrooms", property.bedrooms ?? "—"], ["Bathrooms", property.bathrooms ?? "—"], ["Furnishing", property.furnishing], ["Possession", property.possession], ["Floor", property.floor ?? "—"], ["Parking", property.parking], ["Posted by", property.postedBy]].map(([label, value]) => <div key={label}><span>{label}</span><strong>{value}</strong></div>)}</div></div><div className="detail-section"><h2>Amenities</h2><div className="amenity-list">{property.amenities?.map((item) => <span key={item}><Icon name="check" size={14}/>{item}</span>)}</div></div><div className="detail-section demo-documents"><h2>Documents to review independently</h2><p>This informational checklist is not a document review or legal verification.</p><div>Ownership records <span>Discuss with a qualified adviser</span></div><div>Applicable approvals <span>Review for this property</span></div><div>Agreement terms <span>Review before signing</span></div></div><div className="detail-section"><h2>Location &amp; locality</h2><p>Located in {property.locality}, {property.city}. Exact address is not supplied in this demo listing.</p><a className="text-link" href={`/locality/${slug(property.locality)}`}>Explore {property.locality} <Icon name="arrow" size={15}/></a></div></div><aside className="detail-aside"><div className="consultant-card"><span className="consultant-avatar">S</span><h3>{property.contact?.name ?? "SKYARTH Property"}</h3><p>Property consultant</p><a className="button button-outline full-button" href={`tel:${property.contact?.phone ?? "9945678901"}`}><Icon name="phone"/> Call consultant</a><a className="whatsapp-button" target="_blank" rel="noreferrer" href={`https://wa.me/919945678901?text=${encodeURIComponent(`Hello, I am interested in ${property.title}.`)}`}>WhatsApp enquiry</a></div><LeadForm title="Request more information" related={property.title} compact/><details className="report-listing"><summary>Report listing</summary><form onSubmit={(event) => { event.preventDefault(); setNotice("Listing report saved locally for demo review."); event.currentTarget.reset(); }}><label>Reason<select required><option value="">Choose a reason</option><option>Information appears incorrect</option><option>Listing is no longer available</option><option>Other concern</option></select></label><label>Your message<textarea rows="2" required/></label><button className="button button-outline" type="submit">Submit report</button></form></details>{notice && <p className="form-feedback" role="status">{notice}</p>}</aside></section>{related.length > 0 && <section className="content-section"><div className="section-inner"><SectionHeading eyebrow="KEEP EXPLORING" title="Similar properties"/><div className="property-grid">{related.map((item) => <PropertyCard key={item.id} property={item}/>)}</div></div></section>}</SiteLayout>;
}

function CollectionPage({ title, description, items, kind = "properties", detailPath = "/property/", filters = false }) {
  return <SiteLayout><div className="page-heading-band"><div className="page-width"><span className="eyebrow">SKYARTH PROPERTY · DEMO COLLECTION</span><h1>{title}</h1><p>{description}</p></div></div><section className="content-section page-width">{kind === "properties" ? <div className="property-grid">{items.map((property) => <PropertyCard key={property.id} property={property}/>)}</div> : kind === "projects" ? <div className="project-grid">{items.map((project) => <article className="project-card" key={project.id}><a href={`/project/${project.id}`}><img src={project.image || hero} alt={`${project.name} demo project`} width="700" height="440" loading="lazy" onError={(event) => { event.currentTarget.src = hero; }}/></a><div className="project-card-body"><span className="eyebrow">{project.status} · DEMO PROFILE</span><h2><a href={`/project/${project.id}`}>{project.name}</a></h2><p>{project.location}</p><div className="project-meta"><span>From <strong>{formatPrice(project.startingPrice, true)}</strong></span><span>{project.configurations?.join(" · ")}</span></div><a className="text-link" href={`/project/${project.id}`}>View project <Icon name="arrow" size={15}/></a></div></article>)}</div> : kind === "services" ? <div className="service-grid">{items.map((service) => <article className="service-item" key={service.title}><span className="service-icon"><Icon name="home" size={20}/></span><h2>{service.title}</h2><p>{service.description}</p><a href={`/contact?service=${encodeURIComponent(service.title)}`} className="text-link">Enquire <Icon name="arrow" size={15}/></a></article>)}</div> : kind === "localities" ? <div className="locality-grid">{items.map((locality) => <a className="locality-card" href={`/locality/${locality.slug}`} key={locality.slug}><span className="eyebrow">PUNE · ILLUSTRATIVE DEMO</span><h2>{locality.name}</h2><p>{locality.overview}</p><span className="text-link">Explore locality <Icon name="arrow" size={15}/></span></a>)}</div> : <div className="article-grid">{items.map((article) => <a className="article-card" href={`/insights/${article.slug}`} key={article.slug}><span className="eyebrow">{article.category}</span><h2>{article.title}</h2><p>{article.excerpt}</p><span className="text-link">Read guide <Icon name="arrow" size={15}/></span></a>)}</div>}</section></SiteLayout>;
}

function ProjectDetail({ id }) {
  const { data } = usePortal();
  const project = data.projects.find((item) => item.id === id && item.published);
  if (!project) return <NotFoundPage/>;
  return <SiteLayout><section className="project-detail-hero page-width"><img src={project.image || hero} alt={`${project.name} sample project`} width="1400" height="700" onError={(event) => { event.currentTarget.src = hero; }}/><div className="project-hero-label"><span className="eyebrow">PROJECT PROFILE · DEMO INFORMATION</span><h1>{project.name}</h1><p>{project.location}</p></div></section><section className="detail-layout page-width"><div className="detail-content"><div className="detail-section"><h2>Project overview</h2><p>{project.overview}</p><p>Developer information is a demo profile and does not imply a partnership.</p></div><div className="detail-section"><h2>Configurations &amp; timeline</h2><div className="spec-grid"><div><span>Configurations</span><strong>{project.configurations?.join(", ")}</strong></div><div><span>Starting price</span><strong>{formatPrice(project.startingPrice, true)}</strong></div><div><span>Status</span><strong>{project.status}</strong></div><div><span>Possession timeline</span><strong>{project.possession}</strong></div><div><span>Developer</span><strong>{project.developer}</strong></div></div></div><div className="detail-section"><h2>Amenities</h2><div className="amenity-list">{project.amenities?.map((item) => <span key={item}><Icon name="check" size={14}/>{item}</span>)}</div></div><div className="detail-section"><h2>Location</h2><p>{project.location}. Ask the project team for current availability and details.</p></div></div><aside className="detail-aside"><LeadForm title="Enquire about this project" leadType="Project enquiry" related={project.name} compact/></aside></section></SiteLayout>;
}

function ComparePage() {
  const { data, update } = usePortal();
  const properties = data.compared.map((id) => data.properties.find((item) => item.id === id)).filter(Boolean);
  const lowest = Math.min(...properties.map((item) => item.price));
  const largest = Math.max(...properties.map((item) => item.area));
  const rows = [["Price", (item) => formatPrice(item.price, true), (item) => item.price === lowest], ["Type", (item) => item.type], ["Area", (item) => `${item.area.toLocaleString("en-IN")} ${item.areaUnit}`, (item) => item.area === largest], ["Price / sq.ft.", (item) => formatPrice(item.price / item.area)], ["Bedrooms", (item) => item.bedrooms ?? "—"], ["Bathrooms", (item) => item.bathrooms ?? "—"], ["Furnishing", (item) => item.furnishing], ["Possession", (item) => item.possession], ["Parking", (item) => item.parking], ["Locality", (item) => `${item.locality}, ${item.city}`], ["Amenities", (item) => item.amenities?.join(", ") ?? "—"]];
  return <SiteLayout><div className="page-heading-band"><div className="page-width"><span className="eyebrow">COMPARE DEMO LISTINGS</span><h1>Compare properties</h1><p>Compare up to four selected listings side by side.</p></div></div><section className="content-section page-width">{properties.length < 2 ? <div className="empty-state"><span className="empty-icon"><Icon name="compare" size={26}/></span><h2>Add a couple of properties to compare</h2><p>Choose Compare on any property card. You can add up to four listings.</p><a className="button button-emerald" href="/properties">Browse properties</a></div> : <div className="compare-table-wrap"><table className="compare-table"><thead><tr><th>Property details</th>{properties.map((item) => <th key={item.id}><img src={item.images?.[0] || hero} alt=""/><a href={`/property/${item.id}`}>{item.title}</a><button className="plain-button" onClick={() => update("compared", (ids) => ids.filter((id) => id !== item.id))}>Remove</button></th>)}</tr></thead><tbody>{rows.map(([label, value, highlight]) => <tr key={label}><th>{label}</th>{properties.map((item) => <td className={highlight?.(item) ? "compare-highlight" : ""} key={item.id}>{value(item)}</td>)}</tr>)}</tbody></table></div>}</section></SiteLayout>;
}

function SavedPage({ recent = false }) {
  const { data, update } = usePortal();
  const ids = recent ? data.recent : data.saved;
  const properties = ids.map((id) => data.properties.find((item) => item.id === id && item.published)).filter(Boolean);
  return <SiteLayout><div className="page-heading-band"><div className="page-width"><span className="eyebrow">YOUR PERSONAL COLLECTION</span><h1>{recent ? "Recently viewed" : "Saved properties"}</h1><p>{recent ? "Listings you have opened in this browser." : "Your saved demo listings, available in this browser."}</p></div></div><section className="content-section page-width">{properties.length ? <><div className="collection-actions"><span>{properties.length} {properties.length === 1 ? "property" : "properties"}</span>{recent && <button className="plain-button" onClick={() => update("recent", [])}>Clear history</button>}</div><div className="property-grid">{properties.map((property) => <PropertyCard key={property.id} property={property}/>)}</div></> : <div className="empty-state"><span className="empty-icon"><Icon name={recent ? "home" : "heart"} size={25}/></span><h2>{recent ? "No recently viewed homes yet" : "Nothing saved just yet"}</h2><p>{recent ? "Properties you open will appear here." : "Save a property to keep it close while you explore."}</p><a className="button button-emerald" href="/properties">Explore properties</a></div>}</section></SiteLayout>;
}

function ListPropertyPage() {
  const { update } = usePortal();
  const [step, setStep] = useState(1);
  const [submitted, setSubmitted] = useState("");
  const [form, setForm] = useState({ transaction: "Buy", category: "Residential", type: "Apartment", title: "", city: "Pune", locality: "", area: "", price: "", bedrooms: "", bathrooms: "", name: "", phone: "", email: "", description: "", image: "" });
  const set = (key, value) => setForm((current) => ({ ...current, [key]: value }));
  const next = () => {
    if (step === 3 && (!form.title.trim() || !form.locality.trim() || !form.area || !form.price)) { setSubmitted("Please complete the property title, locality, area and price."); return; }
    if (step === 4 && (!form.name.trim() || !form.phone.trim() || !form.email.trim())) { setSubmitted("Please add your name, phone and email."); return; }
    setSubmitted(""); setStep((number) => Math.min(5, number + 1));
  };
  const finish = () => {
    const submission = { ...form, id: createLocalId("SUB"), status: "Pending review", submittedAt: new Date().toISOString(), published: false, images: form.image ? [form.image] : [hero] };
    update("submissions", (items) => [submission, ...items]);
    setSubmitted(`Your demo submission ${submission.id} is pending admin review. Nothing was sent to a server.`);
    setStep(5);
  };
  return <SiteLayout><div className="page-heading-band"><div className="page-width"><span className="eyebrow">OWNER &amp; AUTHORIZED REPRESENTATIVE ENQUIRIES</span><h1>List your property</h1><p>Share the essentials and the SKYARTH team can follow up in this local demo.</p></div></div><section className="list-form-wrap page-width"><div className="listing-notice"><strong>Local demo submission</strong><span>Your details stay in this browser. This form does not transmit information to a server.</span></div>{step < 5 && <div className="step-progress"><span>Step {step} of 4</span><div><i style={{ width: `${step * 25}%` }}/></div><strong>{["Transaction", "Category", "Property details", "Contact details"][step - 1]}</strong></div>}{submitted && step === 5 ? <div className="success-panel"><span className="success-icon"><Icon name="check" size={25}/></span><h2>Thank you for sharing your property.</h2><p>{submitted}</p><a className="button button-emerald" href="/">Return home</a></div> : <div className="listing-form-card"><h2>{step === 1 ? "What would you like to do?" : step === 2 ? "Choose a category" : step === 3 ? "Tell us about the property" : "How can the team reach you?"}</h2>{step === 1 && <div className="choice-grid">{["Buy", "Rent", "Commercial Sale", "Commercial Lease", "Residential Plots", "Agricultural Land"].map((item) => <button className={form.transaction === item ? "selected" : ""} onClick={() => set("transaction", item)} key={item}>{item}</button>)}</div>}{step === 2 && <div className="choice-grid">{categories.map((item) => <button className={form.category === item ? "selected" : ""} onClick={() => set("category", item)} key={item}>{item}</button>)}</div>}{step === 3 && <div className="form-grid"><label>Property title<input value={form.title} onChange={(event) => set("title", event.target.value)} placeholder="A short description of your property" required/></label><label>Property type<select value={form.type} onChange={(event) => set("type", event.target.value)}>{propertyTypes.map((item) => <option key={item}>{item}</option>)}</select></label><label>City<input value={form.city} onChange={(event) => set("city", event.target.value)} required/></label><label>Locality<input value={form.locality} onChange={(event) => set("locality", event.target.value)} required/></label><label>Area (sq.ft.)<input type="number" min="1" value={form.area} onChange={(event) => set("area", event.target.value)} required/></label><label>Price (INR)<input type="number" min="1" value={form.price} onChange={(event) => set("price", event.target.value)} required/></label><label>Bedrooms<input type="number" min="0" value={form.bedrooms} onChange={(event) => set("bedrooms", event.target.value)}/></label><label>Bathrooms<input type="number" min="0" value={form.bathrooms} onChange={(event) => set("bathrooms", event.target.value)}/></label><label className="form-wide">Image URL (optional)<input type="url" value={form.image} onChange={(event) => set("image", event.target.value)} placeholder="https://"/></label><label className="form-wide">Description<textarea rows="3" value={form.description} onChange={(event) => set("description", event.target.value)} placeholder="Describe the property"/></label></div>}{step === 4 && <div className="form-grid"><label>Full name<input value={form.name} onChange={(event) => set("name", event.target.value)} required/></label><label>Phone<input type="tel" value={form.phone} onChange={(event) => set("phone", event.target.value)} required pattern="[+()0-9 -]{8,}"/></label><label className="form-wide">Email<input type="email" value={form.email} onChange={(event) => set("email", event.target.value)} required/></label><label className="consent-label form-wide"><input type="checkbox" required/><span>I confirm that I am authorized to share these details. This local demo submission will be visible in its admin panel.</span></label></div>}{submitted && step !== 5 && <p className="form-feedback" role="alert">{submitted}</p>}<div className="wizard-actions">{step > 1 && <button className="button button-outline" onClick={() => setStep((number) => number - 1)}>Back</button>}{step < 4 ? <button className="button button-emerald" onClick={next}>Continue <Icon name="arrow" size={16}/></button> : <button className="button button-emerald" onClick={finish}>Review &amp; submit <Icon name="arrow" size={16}/></button>}</div></div>}</section></SiteLayout>;
}

function InfoPage({ title, eyebrow = "SKYARTH PROPERTY", children }) {
  return <SiteLayout><div className="page-heading-band"><div className="page-width"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1></div></div><section className="prose-section page-width">{children}</section></SiteLayout>;
}

function AboutPage() {
  const { data } = usePortal();
  return <InfoPage title="Property guidance, with clarity." eyebrow="ABOUT SKYARTH PROPERTY"><div className="about-hero-image"><img src={hero} alt="Contemporary residential architecture in Pune" width="1400" height="780"/></div><div className="prose-columns"><div><h2>A considered approach to your next move.</h2><p>SKYARTH Property facilitates discovery and transaction support across residential projects, resale homes, commercial spaces and plotted developments.</p><p>From curated site visits and valuation advisory to buyer–seller conversations, leasing support and documentation assistance, our focus is on practical guidance throughout your property journey.</p></div><div><h2>Clear, customer-first support.</h2><p>Every decision belongs to you. Property details in this demo are illustrative; buyers, sellers, landlords and tenants should independently verify relevant information and documentation.</p><a className="button button-emerald" href="/contact">Talk to our team <Icon name="arrow" size={16}/></a></div></div><LeadForm title="Start a conversation" leadType="General enquiry"/></InfoPage>;
}

function ContactPage() {
  const { data } = usePortal();
  return <InfoPage title="Let's talk about your next move." eyebrow="CONTACT"><div className="contact-grid"><div className="contact-details"><span className="eyebrow">SKYARTH PROPERTY · PUNE</span><h2>Here when you need a clear next step.</h2><p>Connect with our team for property discovery, leasing, valuation advisory or a site visit request.</p><div className="contact-line"><span>Office</span><strong>{data.settings.address}</strong></div><div className="contact-line"><span>Call</span><a href={`tel:${data.settings.phone}`}>{data.settings.phone}</a></div><div className="contact-line"><span>Email</span><a href={`mailto:${data.settings.email}`}>{data.settings.email}</a></div><div className="contact-line"><span>Business hours</span><strong>{data.settings.hours}</strong></div><a className="text-link" href={`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(data.settings.address)}`} target="_blank" rel="noreferrer">Get directions <Icon name="arrow" size={15}/></a></div><LeadForm title="Send an enquiry" leadType="Contact enquiry"/></div></InfoPage>;
}

function FaqPage() {
  const { data } = usePortal();
  const [query, setQuery] = useState("");
  const faqs = data.faqs.filter((item) => `${item.question} ${item.answer} ${item.category}`.toLowerCase().includes(query.toLowerCase()));
  return <InfoPage title="Questions, answered." eyebrow="HELP & GUIDANCE"><label className="faq-search">Search questions<input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buying, site visits, documentation…"/></label><div className="faq-list">{faqs.map((item) => <details key={item.question}><summary>{item.question}<span>{item.category}</span></summary><p>{item.answer}</p></details>)}</div><p className="legal-note">Property details shown here are illustrative demo content. Please independently verify property facts and legal documentation.</p></InfoPage>;
}

function LocalityPage({ slugValue }) {
  const { data } = usePortal();
  const locality = data.localities.find((item) => item.slug === slugValue);
  if (!locality) return <NotFoundPage/>;
  const properties = data.properties.filter((item) => item.published && item.locality.toLowerCase() === locality.name.toLowerCase());
  return <SiteLayout><div className="locality-hero page-width"><span className="eyebrow">LOCALITY GUIDE · ILLUSTRATIVE DEMO DATA</span><h1>{locality.name}</h1><p>{locality.overview}</p></div><section className="content-section page-width"><div className="locality-insight-grid"><div><h2>Everyday perspective</h2><p>This profile is a starting point for exploring an area, not a representation of live market research.</p><div className="amenity-list">{locality.highlights.map((item) => <span key={item}><Icon name="check" size={14}/>{item}</span>)}</div><h3>Common property types</h3><p>{locality.types.join(" · ")}</p></div><div className="trend-panel"><span className="eyebrow">ILLUSTRATIVE DEMO DATA</span><h2>Indicative price range</h2><p>{formatPrice(locality.range[0], true)} – {formatPrice(locality.range[1], true)}</p><svg className="trend-chart" viewBox="0 0 520 180" role="img" aria-label="Illustrative sample price trend"><path d="M12 150 C70 130 92 139 135 112 S204 128 255 82 S340 98 375 55 S448 73 506 24"/><path className="chart-baseline" d="M12 160h496"/></svg><small>Sample trend graphic; not a current transaction statistic.</small></div></div><SectionHeading eyebrow="IN THIS AREA" title={`Demo listings around ${locality.name}`}/>{properties.length ? <div className="property-grid">{properties.slice(0, 3).map((property) => <PropertyCard key={property.id} property={property}/>)}</div> : <p>No sample listings for this locality yet.</p>}<div className="related-localities"><h2>Explore other localities</h2><div className="locality-pills">{data.localities.filter((item) => item.slug !== locality.slug).slice(0, 5).map((item) => <a href={`/locality/${item.slug}`} key={item.slug}>{item.name} <Icon name="arrow" size={14}/></a>)}</div></div></section><div className="contact-cta"><h2>Need a local perspective?</h2><p>Tell us what you are looking for and we will help with your next step.</p><a className="button button-emerald" href="/contact">Enquire with SKYARTH <Icon name="arrow" size={16}/></a></div></SiteLayout>;
}

function ArticlePage({ slugValue }) {
  const { data } = usePortal();
  const article = data.articles.find((item) => item.slug === slugValue);
  if (!article) return <NotFoundPage/>;
  return <InfoPage title={article.title} eyebrow={`${article.category} · DEMO GUIDE`}><article className="article-content"><p className="article-intro">{article.excerpt}</p><h2>Start with clear questions</h2><p>Every property journey has its own context. Write down what matters to you, the details you still need to confirm, and any questions that should be reviewed with a qualified professional.</p><h2>Review details independently</h2><p>Property descriptions and example information on this site are illustrative. Ask the relevant parties for current details and independently review all applicable records and agreements before taking a decision.</p><h2>Plan your next step</h2><p>Use a site visit, a careful conversation and suitable independent advice to understand whether a property is right for your needs.</p><a className="button button-emerald" href="/contact">Ask a question <Icon name="arrow" size={16}/></a></article><div className="related-articles"><h2>More guides</h2>{data.articles.filter((item) => item.slug !== slugValue).slice(0, 3).map((item) => <a href={`/insights/${item.slug}`} key={item.slug}>{item.title}<Icon name="arrow" size={15}/></a>)}</div></InfoPage>;
}

function AdminLogin() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState("");
  const submit = (event) => {
    event.preventDefault();
    if (email.trim().toLowerCase() === "admin@skyarthupvc.com" && password === "Skyarth@123") {
      window.sessionStorage.setItem("skyarth-admin-session:v1", "demo");
      window.location.assign("/admin/dashboard");
    } else setError("The demo email or password does not match.");
  };
  return <main className="admin-login-page"><div className="login-panel"><Brand/><span className="eyebrow">LOCAL DEMO ADMIN</span><h1>Welcome back.</h1><p>Sign in to manage this browser's demo portal content.</p><div className="demo-credentials"><strong>Demo access</strong><span>admin@skyarthupvc.com</span><span>Skyarth@123</span><small>These demo credentials are not suitable for production security.</small></div><form className="login-form" onSubmit={submit}><label>Email<input type="email" autoComplete="username" value={email} onChange={(event) => setEmail(event.target.value)} required/></label><label>Password<div className="password-input"><input type={showPassword ? "text" : "password"} autoComplete="current-password" value={password} onChange={(event) => setPassword(event.target.value)} required/><button type="button" onClick={() => setShowPassword(!showPassword)}>{showPassword ? "Hide" : "Show"}</button></div></label>{error && <p className="form-feedback" role="alert">{error}</p>}<button className="button button-emerald full-button" type="submit">Sign in <Icon name="arrow" size={16}/></button></form><a href="/" className="text-link">← Return to SKYARTH Property</a></div></main>;
}

function AdminShell({ section, children }) {
  const [open, setOpen] = useState(false);
  const links = [["Overview", "/admin/dashboard"], ["Properties", "/admin/properties"], ["Projects", "/admin/projects"], ["Leads", "/admin/leads"], ["Website content", "/admin/content"], ["Media", "/admin/media"], ["Team", "/admin/team"], ["Reports", "/admin/reports"], ["Settings", "/admin/settings"]];
  const logout = () => { window.sessionStorage.removeItem("skyarth-admin-session:v1"); window.location.assign("/admin/login"); };
  return <div className="admin-layout"><aside className={`admin-sidebar ${open ? "admin-sidebar-open" : ""}`}><Brand light/><span className="admin-label">ADMINISTRATION</span><nav>{links.map(([label, href]) => <a href={href} key={href} className={section === label.toLowerCase().replace("website ", "") ? "active" : ""}><span>{label.slice(0, 1)}</span>{label}</a>)}</nav><div className="admin-sidebar-bottom"><span>Local browser demo</span><button onClick={logout}>Sign out</button></div></aside><div className="admin-main"><header className="admin-topbar"><button className="icon-button admin-menu-button" aria-label="Open admin menu" onClick={() => setOpen(!open)}><Icon name="menu"/></button><span>SKYARTH <b>/</b> {section}</span><button className="admin-profile" onClick={() => window.location.assign("/")}>Admin demo <span>↗</span></button></header><main className="admin-content">{children}</main></div></div>;
}

function AdminGate({ section, children }) {
  const [allowed, setAllowed] = useState(false);
  useEffect(() => {
    if (window.sessionStorage.getItem("skyarth-admin-session:v1") !== "demo") window.location.replace("/admin/login");
    else setAllowed(true);
  }, []);
  if (!allowed) return <main className="admin-loading"><span>Opening demo workspace…</span></main>;
  return <AdminShell section={section}>{children}</AdminShell>;
}

function DashboardPage() {
  const { data } = usePortal();
  const metrics = [["Total properties", data.properties.length], ["Published properties", data.properties.filter((item) => item.published).length], ["Pending submissions", data.submissions.length], ["Featured properties", data.properties.filter((item) => item.featured).length], ["Total enquiries", data.leads.length], ["New enquiries", data.leads.filter((item) => item.status === "New").length], ["Scheduled site visits", data.leads.filter((item) => item.status === "Site Visit Scheduled").length], ["Published projects", data.projects.filter((item) => item.published).length]];
  return <><div className="admin-page-heading"><div><span className="eyebrow">MONDAY, DEMO WORKSPACE</span><h1>Overview</h1><p>Current activity from locally stored demo data.</p></div><a className="button button-emerald" href="/admin/properties">Manage properties <Icon name="arrow" size={16}/></a></div><div className="metrics-grid">{metrics.map(([label, value], index) => <div className="metric-card" key={label}><span>{label}</span><strong>{value}</strong><small>{index < 4 ? "Current demo inventory" : "Browser-local records"}</small></div>)}</div><div className="admin-dashboard-grid"><section className="admin-panel"><div className="admin-panel-heading"><div><h2>Recent enquiries</h2><p>Latest local demo submissions</p></div><a href="/admin/leads">View all →</a></div>{data.leads.length ? <div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Lead</th><th>Type</th><th>Received</th><th>Status</th></tr></thead><tbody>{data.leads.slice(0, 6).map((lead) => <tr key={lead.id}><td><strong>{lead.name}</strong><small>{lead.id}</small></td><td>{lead.type}</td><td>{new Date(lead.createdAt).toLocaleDateString("en-IN")}</td><td><span className="status-pill">{lead.status}</span></td></tr>)}</tbody></table></div> : <div className="admin-empty">No enquiries in this browser yet.</div>}</section><section className="admin-panel"><div className="admin-panel-heading"><div><h2>Pending property submissions</h2><p>Waiting for review</p></div><a href="/admin/properties">Review →</a></div>{data.submissions.length ? data.submissions.slice(0, 5).map((item) => <div className="activity-row" key={item.id}><span className="activity-dot"/><div><strong>{item.title}</strong><small>{item.locality}, {item.city} · {formatPrice(item.price, true)}</small></div><span className="status-pill">Pending</span></div>) : <div className="admin-empty">No pending property submissions.</div>}</section></div><div className="admin-demo-notice">Demo data is stored locally in this browser and is not synchronized between devices.</div></>;
}

function AdminPropertiesPage() {
  const { data, update } = usePortal();
  const [query, setQuery] = useState("");
  const [editing, setEditing] = useState(null);
  const [message, setMessage] = useState("");
  const listings = data.properties.filter((item) => `${item.title} ${item.locality} ${item.city}`.toLowerCase().includes(query.toLowerCase()));
  const editListing = (item) => setEditing(item ? { ...item } : { id: createLocalId("PROP"), title: "", type: "Apartment", category: "Residential", transaction: "Buy", price: "", area: "", locality: "", city: "Pune", description: "", furnishing: "Unfurnished", possession: "Ready to move", images: [hero], amenities: [], published: false, featured: false, verified: false, bedrooms: 2, bathrooms: 2, postedBy: "SKYARTH Property demo inventory" });
  const updateField = (key, value) => setEditing((item) => ({ ...item, [key]: value }));
  const save = (event) => { event.preventDefault(); update("properties", (items) => editing.isSubmission ? items : items.some((item) => item.id === editing.id) ? items.map((item) => item.id === editing.id ? { ...editing, price: Number(editing.price), area: Number(editing.area) } : item) : [{ ...editing, price: Number(editing.price), area: Number(editing.area) }, ...items]); if (editing.isSubmission) update("submissions", (items) => items.filter((item) => item.id !== editing.id)); setEditing(null); setMessage("Property changes saved locally."); };
  const approveSubmission = (submission) => { update("properties", (items) => [{ ...submission, id: submission.id.replace("SUB", "PROP"), published: true, verified: false, featured: false, amenities: [], furnishing: "Unfurnished", possession: "Ready to move", postedBy: submission.name }, ...items]); update("submissions", (items) => items.filter((item) => item.id !== submission.id)); };
  return <><div className="admin-page-heading"><div><span className="eyebrow">INVENTORY &amp; REVIEW</span><h1>Properties</h1><p>Manage published listings and review owner submissions.</p></div><button className="button button-emerald" onClick={() => editListing(null)}>+ Add property</button></div>{message && <p className="admin-success" role="status">{message}</p>}{editing && <div className="admin-modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setEditing(null); }}><form className="admin-editor" onSubmit={save}><div className="admin-panel-heading"><div><span className="eyebrow">LISTING EDITOR</span><h2>{editing.id && data.properties.some((item) => item.id === editing.id) ? "Edit property" : "Create property"}</h2></div><button type="button" className="icon-button" onClick={() => setEditing(null)} aria-label="Close editor"><Icon name="close"/></button></div><div className="form-grid"><label className="form-wide">Title<input value={editing.title} onChange={(event) => updateField("title", event.target.value)} required/></label><label>Transaction<select value={editing.transaction} onChange={(event) => updateField("transaction", event.target.value)}>{transactionOptions.map((item) => <option key={item}>{item}</option>)}</select></label><label>Category<select value={editing.category} onChange={(event) => updateField("category", event.target.value)}>{categories.map((item) => <option key={item}>{item}</option>)}</select></label><label>Property type<select value={editing.type} onChange={(event) => updateField("type", event.target.value)}>{propertyTypes.map((item) => <option key={item}>{item}</option>)}</select></label><label>Price INR<input type="number" min="1" value={editing.price} onChange={(event) => updateField("price", event.target.value)} required/></label><label>Area (sq.ft.)<input type="number" min="1" value={editing.area} onChange={(event) => updateField("area", event.target.value)} required/></label><label>Locality<input value={editing.locality} onChange={(event) => updateField("locality", event.target.value)} required/></label><label>City<input value={editing.city} onChange={(event) => updateField("city", event.target.value)} required/></label><label className="form-wide">Description<textarea value={editing.description} onChange={(event) => updateField("description", event.target.value)} rows="3"/></label><label className="consent-label"><input type="checkbox" checked={Boolean(editing.published)} onChange={(event) => updateField("published", event.target.checked)}/> Published</label><label className="consent-label"><input type="checkbox" checked={Boolean(editing.featured)} onChange={(event) => updateField("featured", event.target.checked)}/> Featured</label><label className="consent-label"><input type="checkbox" checked={Boolean(editing.verified)} onChange={(event) => updateField("verified", event.target.checked)}/> Explicitly verified</label></div><div className="wizard-actions"><button type="button" className="button button-outline" onClick={() => setEditing(null)}>Cancel</button><button type="submit" className="button button-emerald">Save property</button></div></form></div>}<section className="admin-panel"><div className="admin-toolbar"><label className="admin-search"><Icon name="search"/><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search title or location"/></label><span>{listings.length} listings</span></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Property</th><th>Category</th><th>Price</th><th>Status</th><th>Actions</th></tr></thead><tbody>{listings.map((item) => <tr key={item.id}><td><strong>{item.title}</strong><small>{item.locality}, {item.city} · {item.id}</small></td><td>{item.category}<small>{item.transaction}</small></td><td>{formatPrice(item.price, true)}<small>{item.area.toLocaleString("en-IN")} sq.ft.</small></td><td><span className={`status-pill ${item.published ? "status-published" : ""}`}>{item.published ? "Published" : "Draft"}</span>{item.featured && <small>Featured</small>}</td><td><div className="table-actions"><button onClick={() => editListing(item)}>Edit</button><button onClick={() => update("properties", (items) => items.map((property) => property.id === item.id ? { ...property, published: !property.published } : property))}>{item.published ? "Unpublish" : "Publish"}</button><button onClick={() => { if (window.confirm("Delete this demo property?")) update("properties", (items) => items.filter((property) => property.id !== item.id)); }}>Delete</button></div></td></tr>)}</tbody></table></div></section><section className="admin-panel admin-pending-panel"><div className="admin-panel-heading"><div><h2>Pending listing submissions</h2><p>Submissions are not public until approved.</p></div><span className="status-pill">{data.submissions.length} pending</span></div>{data.submissions.length ? <div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Submitted property</th><th>Contact</th><th>Price</th><th>Actions</th></tr></thead><tbody>{data.submissions.map((item) => <tr key={item.id}><td><strong>{item.title}</strong><small>{item.locality}, {item.city} · {item.id}</small></td><td>{item.name}<small>{item.phone} · {item.email}</small></td><td>{formatPrice(item.price, true)}</td><td><div className="table-actions"><button onClick={() => editListing({ ...item, isSubmission: true })}>Edit</button><button onClick={() => approveSubmission(item)}>Approve</button><button onClick={() => { if (window.confirm("Reject and remove this submission?")) update("submissions", (items) => items.filter((record) => record.id !== item.id)); }}>Reject</button></div></td></tr>)}</tbody></table></div> : <div className="admin-empty">No submissions are waiting for review.</div>}</section></>;
}

function AdminLeadsPage() {
  const { data, update } = usePortal();
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState("All statuses");
  const [selected, setSelected] = useState(null);
  const leads = data.leads.filter((lead) => `${lead.name} ${lead.email} ${lead.phone} ${lead.id} ${lead.related}`.toLowerCase().includes(query.toLowerCase()) && (status === "All statuses" || lead.status === status));
  const exportCsv = () => { const rows = [["Lead ID", "Name", "Phone", "Email", "Type", "Related", "Date", "Status", "Assigned", "Notes"], ...leads.map((item) => [item.id, item.name, item.phone, item.email, item.type, item.related, item.createdAt, item.status, item.assigned, item.notes])]; const csv = rows.map((row) => row.map((value) => `"${String(value ?? "").replaceAll('"', '""')}"`).join(",")).join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "skyarth-demo-enquiries.csv"; anchor.click(); URL.revokeObjectURL(url); };
  const patchLead = (id, values) => update("leads", (items) => items.map((item) => item.id === id ? { ...item, ...values } : item));
  return <><div className="admin-page-heading"><div><span className="eyebrow">ENQUIRY MANAGEMENT</span><h1>Leads &amp; enquiries</h1><p>Manage browser-local demo enquiries and site visit requests.</p></div><button className="button button-outline" onClick={exportCsv}>Export CSV</button></div>{selected && <div className="admin-modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) setSelected(null); }}><section className="admin-editor"><div className="admin-panel-heading"><div><span className="eyebrow">{selected.id}</span><h2>{selected.name}</h2></div><button className="icon-button" onClick={() => setSelected(null)} aria-label="Close enquiry details"><Icon name="close"/></button></div><p>{selected.phone} · {selected.email}</p><p><strong>{selected.type}</strong> · {selected.related || "General enquiry"}</p><p>{selected.message || "No message supplied."}</p><div className="form-grid"><label>Status<select value={selected.status} onChange={(event) => { patchLead(selected.id, { status: event.target.value }); setSelected({ ...selected, status: event.target.value }); }}>{leadStatuses.map((item) => <option key={item}>{item}</option>)}</select></label><label>Assigned consultant<select value={selected.assigned || "Unassigned"} onChange={(event) => { patchLead(selected.id, { assigned: event.target.value }); setSelected({ ...selected, assigned: event.target.value }); }}><option>Unassigned</option>{data.team.map((member) => <option key={member.id}>{member.name}</option>)}</select></label><label>Site visit date<input type="date" value={selected.preferredDate ?? ""} onChange={(event) => { patchLead(selected.id, { preferredDate: event.target.value }); setSelected({ ...selected, preferredDate: event.target.value }); }}/></label><label className="form-wide">Internal notes<textarea rows="4" value={selected.notes ?? ""} onChange={(event) => { patchLead(selected.id, { notes: event.target.value }); setSelected({ ...selected, notes: event.target.value }); }}/></label></div><button className="button button-outline" onClick={() => setSelected(null)}>Done</button></section></div>}<section className="admin-panel"><div className="admin-toolbar"><label className="admin-search"><Icon name="search"/><input placeholder="Search by name, email or lead ID" value={query} onChange={(event) => setQuery(event.target.value)}/></label><select value={status} onChange={(event) => setStatus(event.target.value)}><option>All statuses</option>{leadStatuses.map((item) => <option key={item}>{item}</option>)}</select></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Lead</th><th>Enquiry</th><th>Received</th><th>Status</th><th>Assigned</th><th>Actions</th></tr></thead><tbody>{leads.map((lead) => <tr key={lead.id}><td><strong>{lead.name}</strong><small>{lead.id}<br/>{lead.phone} · {lead.email}</small></td><td>{lead.type}<small>{lead.related || "General enquiry"}</small></td><td>{new Date(lead.createdAt).toLocaleDateString("en-IN")}</td><td><select className="table-status" value={lead.status} onChange={(event) => patchLead(lead.id, { status: event.target.value })}>{leadStatuses.map((item) => <option key={item}>{item}</option>)}</select></td><td>{lead.assigned}</td><td><div className="table-actions"><button onClick={() => setSelected(lead)}>View</button><button onClick={() => { if (window.confirm("Delete this demo enquiry?")) update("leads", (items) => items.filter((entry) => entry.id !== lead.id)); }}>Delete</button></div></td></tr>)}</tbody></table></div>{leads.length === 0 && <div className="admin-empty">No enquiries match these filters.</div>}</section></>;
}

function AdminSimplePage({ section }) {
  const { data, update, reset } = usePortal();
  const [notice, setNotice] = useState("");
  const exportJson = () => { const url = URL.createObjectURL(new Blob([JSON.stringify({ version: 1, data }, null, 2)], { type: "application/json" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "skyarth-demo-backup.json"; anchor.click(); URL.revokeObjectURL(url); };
  const importJson = (event) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const parsed = JSON.parse(String(reader.result)); if (parsed.version !== 1 || !parsed.data || typeof parsed.data !== "object") throw new Error("This backup format is not supported."); Object.entries(parsed.data).forEach(([key, value]) => { if (key in data && value !== undefined) update(key, value); }); setNotice("Backup imported into this browser."); } catch { setNotice("Could not import this file. Choose a valid SKYARTH JSON backup."); } }; reader.readAsText(file); };
  if (section === "projects") return <><div className="admin-page-heading"><div><span className="eyebrow">DEMO PROJECT INVENTORY</span><h1>Projects</h1><p>Manage the sample project catalogue.</p></div></div><div className="admin-table-wrap admin-panel"><table className="admin-table"><thead><tr><th>Project</th><th>Location</th><th>Starting price</th><th>Status</th><th>Actions</th></tr></thead><tbody>{data.projects.map((project) => <tr key={project.id}><td><strong>{project.name}</strong><small>{project.developer}</small></td><td>{project.location}</td><td>{formatPrice(project.startingPrice, true)}</td><td>{project.status}<small>{project.published ? "Published" : "Unpublished"}</small></td><td><div className="table-actions"><button onClick={() => { const name = window.prompt("Edit project name", project.name); if (name?.trim()) update("projects", (items) => items.map((item) => item.id === project.id ? { ...item, name: name.trim() } : item)); }}>Edit name</button><button onClick={() => update("projects", (items) => items.map((item) => item.id === project.id ? { ...item, published: !item.published } : item))}>{project.published ? "Unpublish" : "Publish"}</button><button onClick={() => { if (window.confirm("Delete this demo project?")) update("projects", (items) => items.filter((item) => item.id !== project.id)); }}>Delete</button></div></td></tr>)}</tbody></table><button className="button button-emerald admin-add-project" onClick={() => { const name = window.prompt("New project name"); if (name?.trim()) update("projects", (items) => [{ id: createLocalId("PROJ"), name: name.trim(), developer: "Independent demo profile", location: "Pune", city: "Pune", startingPrice: 0, configurations: ["To be confirmed"], status: "New launch", possession: "On enquiry", amenities: [], image: hero, published: false, overview: "Demo project information." }, ...items]); }}>+ Add project</button></div></>;
  if (section === "content") return <><div className="admin-page-heading"><div><span className="eyebrow">PUBLIC WEBSITE</span><h1>Website content</h1><p>Changes are shown immediately to visitors of this browser.</p></div><button className="button button-emerald" onClick={() => setNotice("Content edits are saved as you make them.")}>Save changes</button></div><section className="admin-panel settings-panel"><h2>Homepage</h2><label>Brand name<input value={data.settings.brand} onChange={(event) => update("settings", (value) => ({ ...value, brand: event.target.value }))}/></label><label>Tagline<input value={data.settings.tagline} onChange={(event) => update("settings", (value) => ({ ...value, tagline: event.target.value }))}/></label><label>Hero headline<input value={data.settings.heroTitle} onChange={(event) => update("settings", (value) => ({ ...value, heroTitle: event.target.value }))}/></label><label>Hero supporting text<textarea rows="3" value={data.settings.heroText} onChange={(event) => update("settings", (value) => ({ ...value, heroText: event.target.value }))}/></label><h2>About &amp; footer</h2><label>Office address<textarea rows="2" value={data.settings.address} onChange={(event) => update("settings", (value) => ({ ...value, address: event.target.value }))}/></label><label>Footer note<input value={data.settings.footerText ?? "Demo property information is illustrative. Please verify independently."} onChange={(event) => update("settings", (value) => ({ ...value, footerText: event.target.value }))}/></label><h2>FAQs</h2>{data.faqs.map((faq, index) => <label key={faq.question}>Question {index + 1}<input value={faq.question} onChange={(event) => update("faqs", (items) => items.map((item, i) => i === index ? { ...item, question: event.target.value } : item))}/></label>)}<button className="button button-outline" onClick={() => update("faqs", (items) => [...items, { question: "New demo question", category: "Enquiries", answer: "Please contact SKYARTH Property for more information." }])}>+ Add FAQ</button></section>{notice && <p className="admin-success">{notice}</p>}</>;
  if (section === "media") return <><div className="admin-page-heading"><div><span className="eyebrow">IMAGE URL LIBRARY</span><h1>Media</h1><p>Demo media uses image URLs. Files are not uploaded to a server.</p></div><button className="button button-emerald" onClick={() => { const url = window.prompt("Image URL"); if (url?.trim()) update("media", (items) => [{ id: createLocalId("MEDIA"), title: "Demo image", alt: "Demo property image", url: url.trim() }, ...items]); }}>+ Add image URL</button></div><div className="media-grid">{data.media.map((item) => <article className="media-card" key={item.id}><img src={item.url || hero} alt={item.alt} onError={(event) => { event.currentTarget.src = hero; }}/><div><strong>{item.title}</strong><small>{item.alt}</small><button onClick={() => update("media", (items) => items.filter((entry) => entry.id !== item.id))}>Remove</button></div></article>)}</div></>;
  if (section === "team") return <><div className="admin-page-heading"><div><span className="eyebrow">DEMO TEAM DIRECTORY</span><h1>Consultants</h1><p>Display-only consultant records; no accounts or permissions are created.</p></div><button className="button button-emerald" onClick={() => { const name = window.prompt("Consultant display name"); if (name?.trim()) update("team", (items) => [{ id: createLocalId("TEAM"), name: name.trim(), role: "Property Consultant", phone: "", email: "", active: true }, ...items]); }}>+ Add consultant</button></div><div className="team-list">{data.team.map((member) => <div className="team-row" key={member.id}><span className="consultant-avatar">{member.name.slice(0, 1)}</span><div><strong>{member.name}</strong><small>{member.role} · {member.phone || "No phone"} · {member.email || "No email"}</small></div><span className="status-pill">{member.active ? "Active" : "Inactive"}</span><button onClick={() => update("team", (items) => items.map((item) => item.id === member.id ? { ...item, active: !item.active } : item))}>{member.active ? "Deactivate" : "Activate"}</button><button onClick={() => { if (window.confirm("Remove this demo consultant?")) update("team", (items) => items.filter((item) => item.id !== member.id)); }}>Remove</button></div>)}</div></>;
  if (section === "reports") { const categoriesCount = categories.map((category) => [category, data.properties.filter((item) => item.category === category).length]); const maxCount = Math.max(...categoriesCount.map((item) => item[1]), 1); const statuses = leadStatuses.slice(0, 6).map((status) => [status, data.leads.filter((item) => item.status === status).length]); return <><div className="admin-page-heading"><div><span className="eyebrow">LOCAL BROWSER ANALYTICS</span><h1>Reports</h1><p>All analytics are based on locally stored demo data.</p></div><button className="button button-outline" onClick={() => { const rows = [["Category", "Properties"], ...categoriesCount]; const csv = rows.map((row) => row.join(",")).join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" })); const a = document.createElement("a"); a.href = url; a.download = "skyarth-demo-report.csv"; a.click(); URL.revokeObjectURL(url); }}>Export CSV</button></div><div className="report-grid"><section className="admin-panel"><h2>Inventory by category</h2>{categoriesCount.map(([label, value]) => <div className="bar-row" key={label}><div><span>{label}</span><strong>{value}</strong></div><div className="bar-track"><i style={{ width: `${value / maxCount * 100}%` }}/></div></div>)}<div className="report-summary">Featured inventory <strong>{data.properties.filter((item) => item.featured).length}</strong></div><div className="report-summary">Project inventory <strong>{data.projects.length}</strong></div></section><section className="admin-panel"><h2>Enquiries by status</h2>{statuses.map(([label, value]) => <div className="bar-row" key={label}><div><span>{label}</span><strong>{value}</strong></div><div className="bar-track"><i style={{ width: `${Math.max(6, value / Math.max(data.leads.length, 1) * 100)}%` }}/></div></div>)}<p className="report-footnote">Enquiry activity has not been independently validated.</p></section></div></>;} 
  return <><div className="admin-page-heading"><div><span className="eyebrow">BROWSER-LOCAL CONTROLS</span><h1>Settings</h1><p>Manage demo business details and local data backups.</p></div><span className="demo-label">DEMO MODE</span></div><section className="admin-panel settings-panel"><h2>Business details</h2><label>Business name<input value={data.settings.brand} onChange={(event) => update("settings", (value) => ({ ...value, brand: event.target.value }))}/></label><label>Tagline<input value={data.settings.tagline} onChange={(event) => update("settings", (value) => ({ ...value, tagline: event.target.value }))}/></label><label>Office address<textarea rows="2" value={data.settings.address} onChange={(event) => update("settings", (value) => ({ ...value, address: event.target.value }))}/></label><label>Phone<input value={data.settings.phone} onChange={(event) => update("settings", (value) => ({ ...value, phone: event.target.value }))}/></label><label>Email<input type="email" value={data.settings.email} onChange={(event) => update("settings", (value) => ({ ...value, email: event.target.value }))}/></label><label>WhatsApp number<input value={data.settings.whatsapp} onChange={(event) => update("settings", (value) => ({ ...value, whatsapp: event.target.value }))}/></label><label>Business hours<input value={data.settings.hours} onChange={(event) => update("settings", (value) => ({ ...value, hours: event.target.value }))}/></label><label>Default currency<input value="INR" readOnly/></label><h2>Backup &amp; restore</h2><div className="backup-actions"><button className="button button-outline" onClick={exportJson}>Export demo data as JSON</button><label className="button button-outline file-import">Import JSON backup<input type="file" accept="application/json,.json" onChange={importJson}/></label></div>{notice && <p className="form-feedback">{notice}</p>}<div className="danger-zone"><div><h3>Reset mock data</h3><p>Restore the original sample inventory and clear browser-local demo changes.</p></div><button className="button button-danger" onClick={() => { if (window.confirm("Reset all SKYARTH demo data in this browser?")) { reset(); setNotice("Demo data restored to defaults."); } }}>Reset demo data</button></div></section></>;
}

function NotFoundPage() {
  return <SiteLayout><section className="not-found"><span className="eyebrow">404 · PAGE NOT FOUND</span><h1>We could not find that page.</h1><p>The link may have moved. Explore the sample properties or return home.</p><div><a className="button button-emerald" href="/properties">Explore properties</a><a className="button button-outline" href="/">Back home</a></div></section></SiteLayout>;
}

function LegalPage({ path }) {
  const config = {
    "/privacy-policy": ["Privacy policy", "Demo interactions may save property preferences, enquiries and settings in local browser storage. This sample portal does not transmit those entries to a server. Browser data is not synchronized across devices. Do not enter sensitive personal information in this demo."],
    "/terms": ["Terms & conditions", "This demonstration portal provides illustrative property and project information for browsing only. It is not a binding offer, representation of availability or professional advice. Use of the demo does not create an agency or transaction relationship."],
    "/disclaimer": ["Important information", "All listing prices, property availability, images, locality ranges, trends, projects and market information are illustrative demo content unless explicitly stated otherwise. SKYARTH Property facilitates property discovery and transaction assistance. Buyers, sellers, landlords and tenants should independently verify property details and all relevant legal documentation before any decision. No legal approval, title status, verification, investment return or transaction outcome is guaranteed."],
  };
  const [title, copy] = config[path] ?? config["/disclaimer"];
  return <InfoPage title={title}><div className="article-content"><p>{copy}</p><p>Contact SKYARTH Property at <a href="mailto:support@skyarthupvc.com">support@skyarthupvc.com</a> for questions about the demo experience.</p></div></InfoPage>;
}

export default function PortalApp({ path = "/", searchStr = "" }) {
  const { data } = usePortal();
  const normalizedPath = path.replace(/\/+$/, "") || "/";
  if (normalizedPath === "/") return <HomePage/>;
  if (normalizedPath === "/admin/login") return <AdminLogin/>;
  if (normalizedPath.startsWith("/admin/")) {
    const section = normalizedPath.split("/")[2] || "dashboard";
    const names = { dashboard: "overview", properties: "properties", projects: "projects", leads: "leads", content: "content", media: "media", team: "team", reports: "reports", settings: "settings" };
    const label = names[section];
    if (!label) return <NotFoundPage/>;
    const children = section === "dashboard" ? <DashboardPage/> : section === "properties" ? <AdminPropertiesPage/> : section === "leads" ? <AdminLeadsPage/> : <AdminSimplePage section={section}/>;
    return <AdminGate section={label}>{children}</AdminGate>;
  }
  if (normalizedPath === "/properties") return <PropertiesPage searchStr={searchStr}/>;
  if (normalizedPath === "/buy") return <PropertiesPage preset="Buy"/>;
  if (normalizedPath === "/rent") return <PropertiesPage preset="Rent"/>;
  if (normalizedPath === "/commercial") return <CollectionPage title="Commercial properties" description="Office, retail and industrial spaces in the demo catalogue." items={data.properties.filter((item) => item.published && item.category === "Commercial")}/>;
  if (normalizedPath === "/plots") return <CollectionPage title="Plots & land" description="Explore sample residential, commercial and agricultural land listings." items={data.properties.filter((item) => item.published && item.category === "Plot")}/>;
  if (normalizedPath === "/projects") return <CollectionPage title="New projects" description="Sample residential and commercial project profiles. No developer partnership is implied." kind="projects" items={data.projects.filter((item) => item.published)}/>;
  if (normalizedPath.startsWith("/property/")) return <PropertyDetail id={normalizedPath.split("/")[2]}/>;
  if (normalizedPath.startsWith("/project/")) return <ProjectDetail id={normalizedPath.split("/")[2]}/>;
  if (normalizedPath === "/saved-properties") return <SavedPage/>;
  if (normalizedPath === "/recently-viewed") return <SavedPage recent/>;
  if (normalizedPath === "/compare") return <ComparePage/>;
  if (normalizedPath === "/list-property") return <ListPropertyPage/>;
  if (normalizedPath === "/services") return <CollectionPage title="Property support, at every step." description="A practical set of services for home seekers, landlords, businesses and investors." kind="services" items={data.services}/>;
  if (normalizedPath === "/about") return <AboutPage/>;
  if (normalizedPath === "/contact") return <ContactPage/>;
  if (normalizedPath === "/faq") return <FaqPage/>;
  if (normalizedPath === "/locality-insights") return <CollectionPage title="A closer look at Pune." description="Illustrative neighbourhood guides to help you explore the city." kind="localities" items={data.localities}/>;
  if (normalizedPath.startsWith("/locality/")) return <LocalityPage slugValue={normalizedPath.split("/")[2]}/>;
  if (normalizedPath === "/insights") return <CollectionPage title="Guides for your next move." description="Useful starting points for buyers, renters, landlords and businesses." kind="articles" items={data.articles}/>;
  if (normalizedPath.startsWith("/insights/")) return <ArticlePage slugValue={normalizedPath.split("/")[2]}/>;
  if (["/privacy-policy", "/terms", "/disclaimer"].includes(normalizedPath)) return <LegalPage path={normalizedPath}/>;
  return <NotFoundPage/>;
}